audit.command:
top=$(git rev-parse --show-toplevel 2>/dev/null) || exit 1
cd "$top" || exit 1
hits=$(git grep -I -l -E 'AKIA[0-9A-Z]{16}|-----BEGIN ((RSA|EC|DSA|OPENSSH|ENCRYPTED|PGP) )?PRIVATE KEY( BLOCK)?-----|gh[pousr]_[A-Za-z0-9]{36}|xox[abprs]-[A-Za-z0-9-]{10,}' 2>/dev/null)
rc=$?
case $rc in
  0) echo "possible secrets committed in:"; printf '%s\n' "$hits" ;;
  1) echo compliant ;;
  *) exit 1 ;;
esac
